#include <iostream>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n;
    in >> n;
    vector<int> p(n);
    for (int i = 0; i < n; ++i) in >> p[i];
    int answer = 0;
    for (int left = 0; left < n; ++left) {
        int sum = 0;
        for (int right = left; right < n; ++right) {
            sum += p[right];
            int length = right - left + 1;
            for (int k = left; k <= right; ++k) {
                if (p[k] * length == sum) {
                    ++answer;
                    break;
                }
            }
        }
    }
    out << answer << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
