#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
struct Cow { char direction; long long x, y; };
struct Event { long long late, early; int blocker, victim; };
void solve(istream& in, ostream& out) {
    int n;
    in >> n;
    vector<Cow> cows(n);
    for (int i = 0; i < n; ++i)
        in >> cows[i].direction >> cows[i].x >> cows[i].y;
    vector<Event> events;
    for (int e = 0; e < n; ++e) {
        if (cows[e].direction != 'E') continue;
        for (int north = 0; north < n; ++north) {
            if (cows[north].direction != 'N') continue;
            long long eastTime = cows[north].x - cows[e].x;
            long long northTime = cows[e].y - cows[north].y;
            if (eastTime <= 0 || northTime <= 0) continue;
            if (eastTime < northTime)
                events.push_back({northTime, eastTime, e, north});
            else if (northTime < eastTime)
                events.push_back({eastTime, northTime, north, e});
        }
    }
    sort(events.begin(), events.end(), [](const Event& a, const Event& b) {
        return a.late < b.late;
    });
    const long long infinity = (1LL << 60);
    vector<long long> stop(n, infinity);
    for (const Event& event : events) {
        if (stop[event.victim] == infinity && stop[event.blocker] > event.early)
            stop[event.victim] = event.late;
    }
    for (int i = 0; i < n; ++i) {
        if (stop[i] == infinity) out << "Infinity\n";
        else out << stop[i] << '\n';
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
